35: int AlignedChunkReader::init(ReadFile* read_file, String m_name,
36:                              TSDataType data_type, Filter* time_filter) {
37:     read_file_ = read_file;
38:     measurement_name_.shallow_copy_from(m_name);
39:     time_decoder_ = DecoderFactory::alloc_time_decoder();
40:     value_decoder_ = nullptr;
41:     time_compressor_ = nullptr;
42:     value_compressor_ = nullptr;
43:     time_filter_ = time_filter;
44:     time_uncompressed_buf_ = nullptr;
45:     value_uncompressed_buf_ = nullptr;
46:     if (IS_NULL(time_decoder_)) {
47:         return E_OOM;
48:     }
49:     return E_OK;
50: }
