52: void AlignedChunkReader::reset() {
53:     time_chunk_meta_ = nullptr;
54:     value_chunk_meta_ = nullptr;
55:     time_chunk_header_.reset();
56:     value_chunk_header_.reset();
57:     cur_time_page_header_.reset();
58:     cur_value_page_header_.reset();
59: 
60:     char* file_data_buf = time_in_stream_.get_wrapped_buf();
61:     if (file_data_buf != nullptr) {
62:         mem_free(file_data_buf);
63:     }
64:     time_in_stream_.clear_wrapped_buf();
65:     time_in_stream_.reset();
66:     file_data_buf = value_in_stream_.get_wrapped_buf();
67:     if (file_data_buf != nullptr) {
68:         mem_free(file_data_buf);
69:     }
70:     value_in_stream_.clear_wrapped_buf();
71:     value_in_stream_.reset();
72:     file_data_time_buf_size_ = 0;
73:     file_data_value_buf_size_ = 0;
74:     time_chunk_visit_offset_ = 0;
75:     value_chunk_visit_offset_ = 0;
76:     page_plan_built_ = false;
77:     current_page_loaded_ = false;
78:     current_page_plan_index_ = 0;
79:     time_predecoded_ = false;
80:     page_all_times_.clear();
81:     page_time_count_ = 0;
82:     page_time_cursor_ = 0;
83: 
84:     // Free leftover uncompressed buffers from the previous chunk.
85:     if (time_uncompressed_buf_ != nullptr && time_compressor_ != nullptr) {
86:         time_compressor_->after_uncompress(time_uncompressed_buf_);
87:         time_uncompressed_buf_ = nullptr;
88:     }
89: 
90:     // Multi-value reset
91:     for (auto* col : value_columns_) {
92:         // Free uncompressed buffer before resetting.
93:         if (col->uncompressed_buf != nullptr && col->compressor != nullptr) {
94:             col->compressor->after_uncompress(col->uncompressed_buf);
95:             col->uncompressed_buf = nullptr;
96:         }
97:         char* buf = col->in_stream.get_wrapped_buf();
98:         if (buf != nullptr) mem_free(buf);
99:         col->in_stream.clear_wrapped_buf();
100:         col->in_stream.reset();
101:         col->in.reset();
102:         col->chunk_header.reset();
103:         col->cur_page_header.reset();
104:         col->file_data_buf_size = 0;
105:         col->chunk_visit_offset = 0;
106:         col->notnull_bitmap.clear();
107:         col->cur_value_index = -1;
108:         col->chunk_meta = nullptr;
109:         for (auto& pps : col->per_page_state) {
110:             pps.predecode_pa.destroy();
111:         }
112:         col->per_page_state.clear();
113:         col->pending_decoded_values.clear();
114:         col->pending_decoded_count = 0;
115:         col->pending_decoded_cursor = 0;
116:         col->pending_decoded = false;
117:         // Note: decoder/compressor are NOT freed here — they are reused by
118:         // alloc_compressor_and_decoder() in load_by_aligned_meta_multi().
119:     }
120:     release_current_page_state();
121:     chunk_pages_.clear();
122:     per_page_times_.clear();
123: }
