125: void AlignedChunkReader::destroy() {
126:     // .clear() leaves the vector's internal heap buffer allocated, which
127:     // mem_free can't reach because we placement-new the reader. swap with
128:     // an empty vector to actually release the backing storage so ASan's
129:     // LeakSanitizer doesn't flag the (rather large) ChunkPageInfo buffers.
130:     std::vector<ChunkPageInfo>{}.swap(chunk_pages_);
131:     std::vector<int64_t>{}.swap(page_all_times_);
132:     if (time_uncompressed_buf_ != nullptr && time_compressor_ != nullptr) {
133:         time_compressor_->after_uncompress(time_uncompressed_buf_);
134:         time_uncompressed_buf_ = nullptr;
135:     }
136:     if (value_uncompressed_buf_ != nullptr && value_compressor_ != nullptr) {
137:         value_compressor_->after_uncompress(value_uncompressed_buf_);
138:         value_uncompressed_buf_ = nullptr;
139:     }
140:     value_page_col_notnull_bitmap_.clear();
141:     value_page_col_notnull_bitmap_.shrink_to_fit();
142:     if (time_decoder_ != nullptr) {
143:         time_decoder_->~Decoder();
144:         DecoderFactory::free(time_decoder_);
145:         time_decoder_ = nullptr;
146:     }
147:     if (value_decoder_ != nullptr) {
148:         value_decoder_->~Decoder();
149:         DecoderFactory::free(value_decoder_);
150:         value_decoder_ = nullptr;
151:     }
152:     if (time_compressor_ != nullptr) {
153:         time_compressor_->~Compressor();
154:         CompressorFactory::free(time_compressor_);
155:         time_compressor_ = nullptr;
156:     }
157:     if (value_compressor_ != nullptr) {
158:         value_compressor_->~Compressor();
159:         CompressorFactory::free(value_compressor_);
160:         value_compressor_ = nullptr;
161:     }
162:     char* buf = time_in_stream_.get_wrapped_buf();
163:     if (buf != nullptr) {
164:         mem_free(buf);
165:         time_in_stream_.clear_wrapped_buf();
166:     }
167:     cur_time_page_header_.reset();
168:     buf = value_in_stream_.get_wrapped_buf();
169:     if (buf != nullptr) {
170:         mem_free(buf);
171:         value_in_stream_.clear_wrapped_buf();
172:     }
173:     cur_value_page_header_.reset();
174:     chunk_header_.~ChunkHeader();
175: 
176:     // Multi-value destroy
177:     for (size_t ci = 0; ci < value_columns_.size(); ci++) {
178:         auto* col = value_columns_[ci];
179:         if (col->decoder != nullptr) {
180:             col->decoder->~Decoder();

650:         value_page_col_notnull_bitmap_.shrink_to_fit();
651:     } else {
652:         ret = E_OK;
653:     }
654:     return ret;
655: }
