657: #define DECODE_TYPED_TV_INTO_TSBLOCK(CppType, ReadType, time_in, value_in,     \
658:                                      row_appender)                             \
659:     do {                                                                       \
660:         uint32_t mask = 1 << 7;                                                \
661:         int64_t time = 0;                                                      \
662:         CppType value;                                                         \
663:         while (time_decoder_->has_remaining(time_in)) {                        \
664:             cur_value_index++;                                                 \
665:             if (value_page_col_notnull_bitmap_.empty() ||                      \
666:                 ((value_page_col_notnull_bitmap_[cur_value_index / 8] &        \
667:                   0xFF) &                                                      \
668:                  (mask >> (cur_value_index % 8))) == 0) {                      \
669:                 ret = time_decoder_->read_int64(time, time_in);                \
670:                 if (ret != E_OK) {                                             \
671:                     break;                                                     \
672:                 }                                                              \
673:                 if (UNLIKELY(!row_appender.add_row())) {                       \
674:                     ret = E_OVERFLOW;                                          \
675:                     break;                                                     \
676:                 }                                                              \
677:                 row_appender.append(0, (char*)&time, sizeof(time));            \
678:                 row_appender.append_null(1);                                   \
679:                 continue;                                                      \
680:             }                                                                  \
681:             assert(value_decoder_->has_remaining(value_in));                   \
682:             if (!value_decoder_->has_remaining(value_in)) {                    \
683:                 return common::E_DATA_INCONSISTENCY;                           \
684:             }                                                                  \
685:             if (UNLIKELY(!row_appender.add_row())) {                           \
686:                 ret = E_OVERFLOW;                                              \
687:                 cur_value_index--;                                             \
688:                 break;                                                         \
689:             } else if (RET_FAIL(time_decoder_->read_int64(time, time_in))) {   \
690:             } else if (RET_FAIL(value_decoder_->read_##ReadType(value,         \
691:                                                                 value_in))) {  \
692:             } else if (filter != nullptr && !filter->satisfy(time, value)) {   \
693:                 row_appender.backoff_add_row();                                \
694:                 continue;                                                      \
695:             } else {                                                           \
696:                 /*std::cout << "decoder: time=" << time << ", value=" << value \
697:                  * << std::endl;*/                                             \
698:                 row_appender.append(0, (char*)&time, sizeof(time));            \
699:                 row_appender.append(1, (char*)&value, sizeof(value));          \
700:             }                                                                  \
701:         }                                                                      \
702:     } while (false)
