704: int AlignedChunkReader::i32_DECODE_TYPED_TV_INTO_TSBLOCK(
705:     ByteStream& time_in, ByteStream& value_in, RowAppender& row_appender,
706:     Filter* filter) {
707:     int ret = E_OK;
708:     uint32_t mask = 1 << 7;
709:     int64_t time = 0;
710:     int32_t value;
711:     while (time_decoder_->has_remaining(time_in)) {
712:         cur_value_index++;
713:         if (value_page_col_notnull_bitmap_.empty() ||
714:             ((value_page_col_notnull_bitmap_[cur_value_index / 8] & 0xFF) &
715:              (mask >> (cur_value_index % 8))) == 0) {
716:             ret = time_decoder_->read_int64(time, time_in);
717:             if (ret != E_OK) {
718:                 break;
719:             }
720:             if (UNLIKELY(!row_appender.add_row())) {
721:                 ret = E_OVERFLOW;
722:                 break;
723:             }
724:             row_appender.append(0, (char*)&time, sizeof(time));
725:             row_appender.append_null(1);
726:             continue;
727:         }
728:         assert(value_decoder_->has_remaining(value_in));
729:         if (!value_decoder_->has_remaining(value_in)) {
730:             return common::E_DATA_INCONSISTENCY;
731:         }
732:         if (UNLIKELY(!row_appender.add_row())) {
733:             ret = E_OVERFLOW;
734:             cur_value_index--;
735:             break;
736:         } else if (RET_FAIL(time_decoder_->read_int64(time, time_in))) {
737:         } else if (RET_FAIL(value_decoder_->read_int32(value, value_in))) {
738:         } else if (filter != nullptr && !filter->satisfy(time, value)) {
739:             row_appender.backoff_add_row();
740:             continue;
741:         } else {
742:             /*std::cout << "decoder: time=" << time << ", value=" << value
743:              * << std::endl;*/
744:             row_appender.append(0, (char*)&time, sizeof(time));
745:             row_appender.append(1, (char*)&value, sizeof(value));
746:         }
747:     }
748:     return ret;
749: }
