751: int AlignedChunkReader::i32_DECODE_TV_BATCH(ByteStream& time_in,
752:                                             ByteStream& value_in,
753:                                             RowAppender& row_appender,
754:                                             Filter* filter) {
755:     int ret = E_OK;
756:     const int BATCH = 129;
757:     int64_t times[BATCH];
758:     int32_t values[BATCH];
759:     const uint32_t null_mask_base = 1 << 7;
760: 
761:     while (time_decoder_->has_remaining(time_in)) {
762:         if (row_appender.remaining() < (uint32_t)BATCH) {
763:             ret = E_OVERFLOW;
764:             break;
765:         }
766: 
767:         // Block-level time filter check
768:         bool block_all_pass = false;
769:         if (filter != nullptr) {
770:             int64_t block_min, block_max;
771:             int block_count;
772:             if (time_decoder_->peek_next_block_range_int64(
773:                     time_in, block_min, block_max, block_count)) {
774:                 if (!filter->satisfy_start_end_time(block_min, block_max)) {
775:                     int skipped = 0;
776:                     time_decoder_->skip_peeked_block_int64(time_in, skipped);
777:                     int nonnull = 0;
778:                     for (int i = 0; i < block_count; ++i) {
779:                         int vi = cur_value_index + 1 + i;
780:                         if (!value_page_col_notnull_bitmap_.empty() &&
781:                             ((value_page_col_notnull_bitmap_[vi / 8] & 0xFF) &
782:                              (null_mask_base >> (vi % 8))) != 0) {
783:                             ++nonnull;
784:                         }
785:                     }
786:                     cur_value_index += block_count;
787:                     if (nonnull > 0) {
788:                         // skip_* may legitimately fail (truncated page) or
789:                         // short-read (corrupt bitmap vs. data); both must
790:                         // abort the loop rather than silently desync the
791:                         // value decoder.  Same defect the multi-value path
792:                         // already guards against.
793:                         int sk = 0;
794:                         if (RET_FAIL(value_decoder_->skip_int32(nonnull, sk,
795:                                                                 value_in))) {
796:                             break;
797:                         }
798:                         if (sk != nonnull) {
799:                             ret = E_TSFILE_CORRUPTED;
800:                             break;
801:                         }
802:                     }
803:                     continue;
804:                 }
805:                 if (filter->contain_start_end_time(block_min, block_max)) {
806:                     block_all_pass = true;
807:                 }
808:             }
809:         }
810: 
811:         int time_count = 0;
812:         if (RET_FAIL(time_decoder_->read_batch_int64(times, BATCH, time_count,
813:                                                      time_in))) {
814:             break;
815:         }
816:         if (time_count == 0) break;
817: 
818:         bool is_null[BATCH];
819:         int nonnull_count = 0;
820:         for (int i = 0; i < time_count; ++i) {
821:             int vi = cur_value_index + 1 + i;
822:             if (value_page_col_notnull_bitmap_.empty() ||
823:                 ((value_page_col_notnull_bitmap_[vi / 8] & 0xFF) &
824:                  (null_mask_base >> (vi % 8))) == 0) {
825:                 is_null[i] = true;
826:             } else {
827:                 is_null[i] = false;
828:                 ++nonnull_count;
829:             }
830:         }
831: 
832:         bool time_mask[BATCH];
833:         int pass_count = time_count;
834:         if (filter != nullptr && !block_all_pass) {
835:             pass_count =
836:                 filter->satisfy_batch_time(times, time_count, time_mask);
837:         }
838: 
839:         if (pass_count == 0) {
840:             if (nonnull_count > 0) {
841:                 int skipped = 0;
842:                 if (RET_FAIL(value_decoder_->skip_int32(nonnull_count, skipped,
843:                                                         value_in))) {
844:                     break;
845:                 }
846:                 if (skipped != nonnull_count) {
847:                     ret = E_TSFILE_CORRUPTED;
848:                     break;
849:                 }
850:             }
851:             cur_value_index += time_count;
852:             continue;
853:         }
854: 
855:         int value_count = 0;
856:         if (nonnull_count > 0) {
857:             if (RET_FAIL(value_decoder_->read_batch_int32(
858:                     values, nonnull_count, value_count, value_in))) {
859:                 break;
860:             }
861:         }
862: 
863:         int val_idx = 0;
864:         for (int i = 0; i < time_count; ++i) {
865:             cur_value_index++;
866:             if (filter != nullptr && !block_all_pass && !time_mask[i]) {
867:                 if (!is_null[i]) ++val_idx;
868:                 continue;
869:             }
870:             if (is_null[i]) {
871:                 if (UNLIKELY(!row_appender.add_row())) {
872:                     ret = E_OVERFLOW;
873:                     break;
874:                 }
875:                 row_appender.append(0, (char*)&times[i], sizeof(int64_t));
876:                 row_appender.append_null(1);
877:             } else {
878:                 int32_t val = values[val_idx++];
879:                 if (filter != nullptr && !block_all_pass &&
880:                     !filter->satisfy(times[i], (int64_t)val)) {
881:                     continue;
882:                 }
883:                 if (UNLIKELY(!row_appender.add_row())) {
884:                     ret = E_OVERFLOW;
885:                     break;
886:                 }
887:                 row_appender.append(0, (char*)&times[i], sizeof(int64_t));
888:                 row_appender.append(1, (char*)&val, sizeof(int32_t));
889:             }
890:         }
891:         if (ret != E_OK) break;
892:     }
893:     return ret;
894: }
